async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const isValid = tool.validateInput(input);
  if (!isValid) {
    const messages = (tool.validateInput.errors ?? []).map(err => {
      const field = err.instancePath || (err.params && 'missingProperty' in err.params ? String(err.params.missingProperty) : 'input');
      return `${field} ${err.message ?? 'is invalid'}`;
    });
    const resultMessage = `Validation failed: ${messages.join(', ')}`;
    log.warn('tool', 'input validation failed', {name, errors: messages});
    return {result: resultMessage};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
